From 172f393e20dad1a69e9a79c3d6f8d4c78f921b2f Mon Sep 17 00:00:00 2001
From: DavidKorczynski <david@adalogics.com>
Date: Tue, 23 Feb 2021 23:19:50 +0000
Subject: [PATCH] pack: fix type confusion bugs. Amongst other OSS-Fuzz
 5136174263566336 (#3115)

Signed-off-by: davkor <david@adalogics.com>
---
 src/flb_pack.c | 6 ++++++
 1 file changed, 6 insertions(+)

diff --git a/src/flb_pack.c b/src/flb_pack.c
index 6c3e1a3..c1bc9b0 100644
--- a/src/flb_pack.c
+++ b/src/flb_pack.c
@@ -840,6 +840,9 @@ flb_sds_t flb_pack_msgpack_to_json_format(const char *data, uint64_t bytes,
     while (msgpack_unpack_next(&result, data, bytes, &off) == ok) {
         /* Each array must have two entries: time and record */
         root = result.data;
+        if (root.type != MSGPACK_OBJECT_ARRAY) {
+            continue;
+        }
         if (root.via.array.size != 2) {
             continue;
         }
@@ -849,6 +852,9 @@ flb_sds_t flb_pack_msgpack_to_json_format(const char *data, uint64_t bytes,

         /* Get the record/map */
         map = root.via.array.ptr[1];
+        if (map.type != MSGPACK_OBJECT_MAP) {
+            continue;
+        }
         map_size = map.via.map.size;

         if (date_key != NULL) {
